gaster_chaos() { clear; tput civvis; trap "tput cnorm; clear; return" INT TERM EXIT; s=("➔" "➘" "▲" "▼" "░" "▒" "▓" "█" "☠" "☤" "☥" "☯" "☰" "☹" "☺" "☻" "☼" "☽" "☾" "♈" "♉" "♊" "♋" "♌" "♍" "♎" "♏" "♐" "♑" "♒" "♓" "♔" "♕" "♖" "♗" "♘" "♙" "♚" "♛" "♜" "♝" "♞" "♟" "♠" "♡" "♢" "♣" "♤" "♥" "♦" "♧" "♨" "♩" "♪" "♫" "♬"); while true; do [ $((RANDOM%100)) -lt 5 ] && tput cup $((RANDOM%$(tput lines))) $((RANDOM%$(tput cols))); c=$((RANDOM%100)); if [ $c -lt 85 ]; then COLOR='\033[38;5;208m'; elif [ $c -lt 92 ]; then COLOR='\033[38;5;196m'; else COLOR='\033[38;5;231m'; fi; [ $((RANDOM%100)) -lt 3 ] && echo ""; printf "${COLOR}%s\033[0m" "${s[$((RANDOM%${#s[@]}))]}"; sleep "0.0$(( (RANDOM % 2) + 1 ))"; done; }
